import{_ as e,c as a,o as l,a4 as o}from"./chunks/framework.D5y910bP.js";const h=JSON.parse('{"title":"Cloudflare SaaS setup","description":"","frontmatter":{"date":"2025-01-21T00:00:00.000Z","tags":["cloudflare","saas","domain","proxy","cname"],"title":"Cloudflare SaaS setup"},"headers":[],"relativePath":"blog/cloudflare-saas-setup.md","filePath":"blog/cloudflare-saas-setup.md","lastUpdated":null}'),r={name:"blog/cloudflare-saas-setup.md"},t=o('<h1 id="cloudflare-saas-setup" tabindex="-1">Cloudflare SaaS setup <a class="header-anchor" href="#cloudflare-saas-setup" aria-label="Permalink to &quot;Cloudflare SaaS setup&quot;">​</a></h1><p>Setting up a Cloudflare zone for SaaS</p><blockquote><p><a href="https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/getting-started/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/getting-started/</a></p></blockquote><ul><li>Add your zone to Cloudflare on a Free plan.</li><li>Enable Cloudflare for SaaS for your zone. <ul><li>Select your account and zone.</li><li>Go to SSL/TLS &gt; Custom Hostnames.</li><li>Select Enable.</li><li>Confirm Payment</li></ul></li><li>Review the Hostname prioritization guidelines. Wildcard custom hostnames behave differently than an exact hostname match. <ul><li><a href="https://developers.cloudflare.com/ssl/reference/certificate-and-hostname-priority/#hostname-priority" target="_blank" rel="noreferrer">https://developers.cloudflare.com/ssl/reference/certificate-and-hostname-priority/#hostname-priority</a></li></ul></li><li>Create fallback origin <ul><li>Create a proxied A, AAAA, or CNAME record pointing to the IP address of your fallback origin (where Cloudflare will send custom hostname traffic). <ul><li><code>A proxy-fallback &lt;origin-ip&gt; Proxied</code></li><li><code>AAAA proxy-fallback 100:: Proxied</code> (for worker)</li><li>or <code>A proxy-fallback 192.0.2.0 Proxied</code> (for worker)</li></ul></li><li>Designate that record as your fallback origin. <ul><li>Go to SSL/TLS &gt; Custom Hostnames.</li><li>For Fallback Origin, enter the hostname for your fallback origin.</li><li>Select Add Fallback Origin.</li><li>Once you have added the fallback origin, confirm that its status is Active.</li></ul></li><li>Workers as your fallback origin <ul><li>Ensure the fallback origin only has an originless DNS record (100:😃</li><li>In that same zone, navigate to Workers Routes.</li><li>Click Add route.</li><li>Decide whether you want traffic bound for your SaaS zone (example.com) to go to that Worker <ul><li><a href="https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/worker-as-origin/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/worker-as-origin/</a></li></ul></li></ul></li></ul></li><li>(Optional) Create CNAME target <ul><li>Create a proxied CNAME that points your CNAME target to your fallback origin (can be a wildcard such as *.customers.saasprovider.com).</li><li><code>CNAME .customers proxy-fallback.saasprovider.com Proxied</code></li></ul></li></ul>',4),i=[t];function s(c,d,n,u,f,p){return l(),a("div",null,i)}const g=e(r,[["render",s]]);export{h as __pageData,g as default};
